:root {
  --bg: #f4f7fb;
  --bg-2: #e8eef6;
  --panel: rgba(255, 255, 255, 0.92);
  --panel-2: rgba(248, 250, 252, 0.96);
  --surface: #ffffff;
  --surface-2: #eef3f8;
  --text: #172033;
  --muted: #667085;
  --soft: #344054;
  --line: rgba(25, 41, 57, 0.14);
  --teal: #0f766e;
  --blue: #2563eb;
  --green: #178a5a;
  --amber: #b7791f;
  --red: #fb7185;
  --violet: #7c3aed;
  --ink: #ffffff;
  --shadow: 0 18px 46px rgba(15, 23, 42, 0.11);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
}

body {
  min-width: 320px;
  margin: 0;
  color: var(--text);
  background:
    radial-gradient(circle at 18% 14%, rgba(15, 118, 110, 0.1), transparent 28%),
    radial-gradient(circle at 76% 0%, rgba(37, 99, 235, 0.09), transparent 30%),
    linear-gradient(135deg, #f7fafc 0%, #eef3f8 48%, #f8fbfd 100%);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 14px;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

button:focus-visible,
input:focus-visible {
  outline: 2px solid rgba(45, 212, 191, 0.72);
  outline-offset: 3px;
}

.app-shell {
  display: grid;
  grid-template-columns: 268px minmax(0, 1fr);
  min-height: 100vh;
}

.sidebar {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 18px;
  height: 100vh;
  overflow-y: auto;
  padding: 22px 16px;
  border-right: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(17, 24, 35, 0.94), rgba(8, 11, 16, 0.96)),
    rgba(9, 11, 16, 0.78);
  backdrop-filter: blur(20px);
}

/* In una viewport bassa la sidebar deve scorrere, non comprimere il tenant. */
.brand,
.workspace-card,
.nav-list,
.local-card {
  flex-shrink: 0;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 54px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  border-radius: 8px;
  padding: 10px;
  background: rgba(255, 255, 255, 0.03);
}

.brand-mark {
  position: relative;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(45, 212, 191, 0.38);
  border-radius: 8px;
  background: linear-gradient(145deg, rgba(45, 212, 191, 0.24), rgba(96, 165, 250, 0.18));
  box-shadow: inset 0 0 18px rgba(45, 212, 191, 0.16), 0 12px 30px rgba(45, 212, 191, 0.08);
  overflow: hidden;
}

.brand-mark::before,
.brand-mark::after,
.brand-mark span {
  content: "";
  position: absolute;
  border-radius: 50%;
}

.brand-mark::before {
  width: 22px;
  height: 22px;
  border: 1px solid rgba(238, 243, 247, 0.65);
}

.brand-mark::after {
  width: 7px;
  height: 7px;
  background: var(--teal);
  box-shadow: 0 0 18px rgba(45, 212, 191, 0.72);
}

.brand-mark span {
  width: 34px;
  height: 1px;
  background: rgba(96, 165, 250, 0.52);
  transform: rotate(-32deg);
}

.brand strong,
.local-card strong {
  display: block;
}

.sidebar,
.sidebar .brand strong,
.sidebar .workspace-top strong,
.sidebar .workspace-stats strong,
.sidebar .local-card strong,
.sidebar .nav-item {
  color: #eef3f7;
}

.brand span,
.local-card p,
.workspace-card span,
.nav-item small,
.live-tile p,
.section-heading p,
.hero-copy p,
.signal-step p,
.drop-panel p,
.console-feed,
.doc-card p,
.brain-detail p,
.export-item p,
.report-preview p,
.message .sources,
.question-card span {
  color: var(--muted);
}

.nav-list {
  display: grid;
  gap: 8px;
}

.nav-item {
  display: grid;
  grid-template-columns: 38px 1fr;
  align-items: center;
  gap: 11px;
  min-height: 58px;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 8px 10px;
  color: var(--soft);
  background: rgba(255, 255, 255, 0.025);
  text-align: left;
}

/* `display: grid` non deve annullare l'attributo hidden usato per i ruoli. */
.nav-item[hidden] {
  display: none !important;
}

.nav-item span:first-child {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 7px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(148, 163, 184, 0.08);
  color: var(--soft);
  font-size: 16px;
  font-weight: 800;
}

.nav-item span:last-child {
  display: grid;
  gap: 2px;
}

.nav-item strong {
  display: block;
  font-size: 14px;
}

.nav-item small {
  display: block;
  font-size: 11px;
  line-height: 1.2;
}

.nav-item:hover,
.nav-item.active {
  border-color: rgba(45, 212, 191, 0.34);
  background:
    linear-gradient(135deg, rgba(45, 212, 191, 0.13), rgba(96, 165, 250, 0.08)),
    rgba(255, 255, 255, 0.04);
  color: #ffffff;
}

.nav-item.active span:first-child {
  background: var(--teal);
  color: var(--ink);
}

.workspace-card {
  position: relative;
  display: grid;
  gap: 14px;
  border: 1px solid rgba(45, 212, 191, 0.18);
  border-radius: 8px;
  padding: 14px;
  background:
    radial-gradient(circle at 80% 20%, rgba(45, 212, 191, 0.18), transparent 40%),
    rgba(24, 32, 44, 0.62);
  overflow: hidden;
}

.workspace-top {
  display: grid;
  gap: 3px;
}

.workspace-top span,
.workspace-stats span {
  font-size: 11px;
  text-transform: uppercase;
}

.workspace-top strong {
  font-size: 16px;
}

.workspace-top small {
  color: rgba(226, 232, 240, 0.76);
  font-size: 11px;
  line-height: 1.25;
  word-break: break-word;
}

.workspace-brain {
  position: relative;
  height: 76px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 8px;
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(15, 23, 42, 0.92), rgba(15, 23, 42, 0.32), rgba(15, 23, 42, 0.88)),
    url("assets/dossiermind-digital-brain-hero.png") center / cover no-repeat;
  box-shadow: inset 0 0 34px rgba(20, 184, 166, 0.12);
}

.workspace-brain::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(rgba(148, 163, 184, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.07) 1px, transparent 1px);
  background-size: 18px 18px;
  opacity: 0.55;
}

.brain-thread,
.brain-dot {
  content: "";
  position: absolute;
}

.brain-thread {
  height: 1px;
  transform-origin: left center;
  background: linear-gradient(90deg, rgba(45, 212, 191, 0.18), rgba(96, 165, 250, 0.45));
}

.brain-thread.t1 {
  left: 45px;
  top: 34px;
  width: 130px;
  transform: rotate(-10deg);
}

.brain-thread.t2 {
  left: 72px;
  top: 48px;
  width: 86px;
  transform: rotate(-34deg);
}

.brain-thread.t3 {
  left: 54px;
  top: 22px;
  width: 112px;
  transform: rotate(31deg);
}

.brain-dot {
  border-radius: 50%;
  box-shadow: 0 0 18px rgba(45, 212, 191, 0.3);
}

.brain-dot.d1 {
  left: 28px;
  top: 20px;
  width: 7px;
  height: 7px;
  background: var(--blue);
}

.brain-dot.d2 {
  left: 95px;
  top: 32px;
  width: 13px;
  height: 13px;
  background: var(--teal);
}

.brain-dot.d3 {
  right: 36px;
  top: 18px;
  width: 8px;
  height: 8px;
  background: var(--amber);
}

.brain-dot.d4 {
  right: 66px;
  bottom: 18px;
  width: 7px;
  height: 7px;
  background: var(--green);
}

.brain-dot.d5 {
  left: 62px;
  bottom: 20px;
  width: 6px;
  height: 6px;
  background: #94a3b8;
}

.workspace-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.workspace-stats div {
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 8px;
  padding: 9px 8px;
  background: rgba(9, 11, 16, 0.28);
}

.workspace-stats strong {
  display: block;
  font-size: 18px;
  line-height: 1;
}

.local-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: rgba(24, 32, 44, 0.74);
}

.local-card p {
  margin: 0;
  line-height: 1.45;
}

.local-card {
  display: grid;
  grid-template-columns: 16px 1fr;
  gap: 10px;
  margin-top: auto;
}

.status-dot {
  width: 10px;
  height: 10px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 5px rgba(94, 227, 108, 0.14), 0 0 24px rgba(94, 227, 108, 0.42);
}

.main-content {
  min-width: 0;
  padding: 28px;
}

.main-content.is-operational .topbar {
  align-items: center;
  margin-bottom: 12px;
}

.main-content.is-operational .topbar h1 {
  display: none;
}

.main-content.is-operational .identity-strip {
  margin-bottom: 12px;
}

.main-content.is-operational .live-strip {
  margin-bottom: 14px;
}

.main-content.is-operational .live-tile {
  min-height: 82px;
  padding: 11px 13px;
}

.main-content.is-operational .live-tile strong {
  margin-top: 5px;
  font-size: 23px;
}

.main-content.is-operational .live-tile p {
  margin-top: 5px;
  font-size: 11px;
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 22px;
  margin-bottom: 20px;
}

.topbar h1 {
  max-width: 980px;
  margin: 4px 0 0;
  font-size: 30px;
  line-height: 1.12;
  letter-spacing: 0;
}

.eyebrow {
  margin: 0;
  color: var(--teal);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0;
}

.eyebrow-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.demo-disclosure {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  border: 1px solid rgba(217, 119, 6, 0.26);
  border-radius: 999px;
  padding: 0 9px;
  color: #92400e;
  background: rgba(254, 243, 199, 0.86);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.topbar-actions,
.action-row,
.section-heading,
.panel-title,
.ask-form,
.doc-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.topbar-actions,
.section-heading,
.panel-title {
  justify-content: space-between;
}

.action-row.compact {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.primary-btn,
.ghost-btn,
.danger-btn,
.chip {
  min-height: 40px;
  border: 1px solid rgba(25, 41, 57, 0.18);
  border-radius: 8px;
  padding: 0 14px;
  background: #ffffff;
  color: var(--text);
  white-space: nowrap;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
}

.danger-btn {
  min-height: 40px;
  border: 1px solid rgba(190, 24, 93, 0.25);
  border-radius: 8px;
  padding: 0 14px;
  color: #9f1239;
  background: rgba(255, 241, 242, 0.92);
  font-weight: 850;
  white-space: nowrap;
}

.danger-btn:hover {
  border-color: rgba(190, 24, 93, 0.48);
  background: #ffe4e6;
}

.primary-btn {
  border-color: #0f766e;
  background: linear-gradient(135deg, #0f766e, #1d4ed8);
  color: #ffffff;
  font-weight: 900;
  box-shadow: 0 10px 24px rgba(29, 78, 216, 0.18);
}

.primary-btn:hover {
  filter: brightness(1.06);
}

.ghost-btn {
  color: #172033;
}

.ghost-btn:hover,
.chip:hover,
.chip.active {
  border-color: rgba(37, 99, 235, 0.34);
  background: rgba(37, 99, 235, 0.08);
  color: #1d4ed8;
}

.live-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 22px;
}

.live-tile {
  min-height: 104px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 15px;
  background: #ffffff;
  box-shadow: var(--shadow);
}

.live-tile span {
  color: #475467;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.live-tile strong {
  display: block;
  margin-top: 8px;
  font-size: 30px;
  line-height: 1;
  color: #172033;
}

.live-tile p {
  margin: 8px 0 0;
  color: #667085;
}

.studio-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.studio-blocked-overview {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  border: 1px solid rgba(220, 38, 38, 0.48);
  border-left: 7px solid #dc2626;
  border-radius: 10px;
  padding: 13px 15px;
  background: linear-gradient(90deg, #fff1f2, rgba(254, 226, 226, 0.72));
  color: #7f1d1d;
  box-shadow: 0 14px 34px rgba(185, 28, 28, 0.11);
}

.studio-summary .studio-blocked-overview span { border-radius: 999px; padding: 6px 9px; background: #dc2626; color: #ffffff; font-size: 10px; font-weight: 950; letter-spacing: 0.06em; white-space: nowrap; }
.studio-blocked-overview strong { color: #7f1d1d; font-size: 17px; white-space: nowrap; }
.studio-summary .studio-blocked-overview p { margin: 0; color: #991b1b; font-size: 12px; line-height: 1.4; }

.studio-summary article,
.client-card,
.governance-card,
.audit-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: var(--shadow);
}

.studio-summary article {
  min-height: 112px;
  padding: 16px;
}

.studio-summary span,
.client-card-top span,
.governance-card span {
  color: #475467;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.studio-summary strong {
  display: block;
  margin-top: 8px;
  color: var(--text);
  font-size: 24px;
  line-height: 1.1;
}

.studio-summary p,
.client-card p,
.governance-card p,
.audit-item p,
.tenant-line {
  color: var(--muted);
}

.client-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(260px, 1fr));
  gap: 16px;
}

.client-card {
  display: grid;
  gap: 14px;
  padding: 16px;
}

.client-card.active {
  border-color: rgba(15, 118, 110, 0.46);
  box-shadow: 0 18px 46px rgba(15, 118, 110, 0.12);
}

.client-card.consent-revoked {
  border-color: rgba(220, 38, 38, 0.42);
  background: linear-gradient(180deg, #ffffff, rgba(254, 242, 242, 0.88));
  box-shadow: 0 18px 46px rgba(185, 28, 28, 0.12);
}

.client-card.consent-revoked.active {
  border-color: rgba(220, 38, 38, 0.72);
  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.12), 0 18px 46px rgba(185, 28, 28, 0.16);
}

.tenant-blocked-banner {
  display: grid;
  gap: 4px;
  border: 1px solid rgba(220, 38, 38, 0.35);
  border-left: 5px solid #dc2626;
  border-radius: 9px;
  padding: 12px;
  background: linear-gradient(135deg, rgba(254, 226, 226, 0.96), rgba(255, 247, 237, 0.92));
  color: #7f1d1d;
}

.tenant-blocked-banner span {
  color: #b91c1c;
  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.tenant-blocked-banner strong { font-size: 13px; line-height: 1.35; }
.tenant-blocked-banner small { color: #991b1b; line-height: 1.35; }

.tenant-entry-btn:disabled {
  border-color: rgba(185, 28, 28, 0.22);
  background: #e5e7eb;
  color: #7f1d1d;
  box-shadow: none;
  cursor: not-allowed;
  filter: grayscale(0.25);
}

.client-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.client-card h3,
.governance-card h3 {
  margin: 6px 0 4px;
  font-size: 19px;
}

.client-card p,
.governance-card p,
.audit-item p,
.tenant-line {
  margin: 0;
  line-height: 1.45;
}

.client-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.client-metrics div {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  background: #ffffff;
}

.client-metrics strong {
  display: block;
  font-size: 22px;
}

.client-metrics span {
  color: var(--muted);
  font-size: 12px;
}

.tenant-line {
  min-height: 44px;
  padding: 10px;
  border: 1px dashed rgba(37, 99, 235, 0.24);
  border-radius: 8px;
  background: rgba(37, 99, 235, 0.05);
  font-size: 12px;
}

.governance-layout {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(320px, 1.08fr);
  gap: 16px;
}

#consentPanel {
  display: grid;
  gap: 16px;
}

.governance-card {
  padding: 18px;
}

.access-blocked-banner {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  border: 1px solid rgba(220, 38, 38, 0.48);
  border-left: 7px solid #dc2626;
  border-radius: 12px;
  padding: 16px;
  background: radial-gradient(circle at 88% 12%, rgba(248, 113, 113, 0.2), transparent 34%), linear-gradient(135deg, #fff1f2, #fef2f2);
  color: #7f1d1d;
  box-shadow: 0 20px 46px rgba(185, 28, 28, 0.14);
}

.blocked-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #dc2626;
  color: #ffffff;
  font-size: 30px;
  line-height: 1;
  box-shadow: 0 0 0 8px rgba(220, 38, 38, 0.1);
}

.access-blocked-banner span { color: #dc2626; font-size: 10px; font-weight: 950; letter-spacing: 0.1em; }
.access-blocked-banner h3 { margin: 2px 0 4px; color: #7f1d1d; font-size: 23px; }
.access-blocked-banner p { margin: 0; color: #991b1b; line-height: 1.45; }
.access-blocked-banner > strong { border-radius: 999px; padding: 8px 12px; background: #dc2626; color: #ffffff; white-space: nowrap; }

.security-footnote {
  display: block;
  margin-top: 12px;
  border-top: 1px solid var(--line);
  padding-top: 10px;
  color: var(--muted);
  line-height: 1.45;
}

.audit-panel {
  padding: 16px;
}

.audit-integrity {
  display: grid;
  gap: 10px;
  margin-bottom: 12px;
  border: 1px solid rgba(15, 118, 110, 0.24);
  border-radius: 10px;
  padding: 13px;
  background: linear-gradient(135deg, rgba(240, 253, 250, 0.96), rgba(239, 246, 255, 0.9));
}

.integrity-status { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.integrity-status span { color: #047857; font-size: 11px; font-weight: 950; letter-spacing: 0.07em; }
.integrity-status i { display: inline-block; width: 8px; height: 8px; margin-right: 5px; border-radius: 50%; background: #10b981; box-shadow: 0 0 0 5px rgba(16, 185, 129, 0.12); }
.integrity-status strong { color: var(--text); font-size: 13px; }
.integrity-root span { display: block; margin-bottom: 4px; color: var(--muted); font-size: 10px; font-weight: 900; text-transform: uppercase; }
.integrity-root code { display: block; overflow: hidden; color: #0f766e; font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.integrity-flow { display: flex; align-items: center; gap: 5px; color: var(--muted); font-size: 10px; font-weight: 850; }
.integrity-flow span { border: 1px solid rgba(37, 99, 235, 0.14); border-radius: 6px; padding: 5px 7px; background: rgba(255, 255, 255, 0.78); }
.integrity-flow b { color: #0f766e; }
.audit-integrity p { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.45; }

.audit-list {
  display: grid;
  gap: 10px;
  max-height: 620px;
  overflow: auto;
}

.audit-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 104px;
  gap: 10px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: #ffffff;
}

.audit-item span {
