  display: block;
  margin-top: 9px;
  font-size: 20px;
}

.artifact-grid p {
  margin: 8px 0 0;
  font-size: 12px;
  line-height: 1.45;
}

.artifact-grid .artifact-trust {
  border-color: rgba(15, 118, 110, 0.28);
  background: linear-gradient(145deg, #effcf9, #eef4ff);
}

.progress-track {
  height: 10px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.12);
  overflow: hidden;
  margin: 14px 0;
}

#progressBar {
  width: 0%;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--teal), var(--blue), var(--amber));
  transition: width 180ms ease;
}

.digest-chamber {
  display: grid;
  grid-template-columns: minmax(215px, 0.9fr) minmax(250px, 1.15fr) minmax(330px, 1.7fr);
  gap: 12px;
  min-height: 172px;
  margin: 0 0 10px;
  padding: 12px;
  border: 1px solid rgba(45, 212, 191, 0.28);
  border-radius: 12px;
  overflow: hidden;
  background: linear-gradient(120deg, #07111f, #0c1d2f 48%, #101827);
  color: #e8f3ff;
  box-shadow: 0 18px 46px rgba(15, 23, 42, 0.16);
}

.digest-label { display: flex; align-items: center; gap: 7px; color: #7dd3fc; font-size: 9px; font-weight: 950; letter-spacing: 0.13em; }
.live-dot { width: 7px; height: 7px; border-radius: 50%; background: #2dd4bf; box-shadow: 0 0 12px #2dd4bf; }
.digest-queue-panel { min-width: 0; }
.digest-queue { display: grid; gap: 4px; max-height: 132px; margin-top: 8px; overflow: auto; }
.digest-empty { display: block; max-width: 250px; color: #91a4ba; font-size: 11px; line-height: 1.45; }
.digest-queue-item { display: grid; grid-template-columns: 24px minmax(0, 1fr); align-items: center; gap: 7px; padding: 5px 7px; border: 1px solid rgba(148, 163, 184, 0.16); border-radius: 6px; color: #aab9c9; background: rgba(255, 255, 255, 0.025); }
.digest-queue-item span { display: grid; place-items: center; width: 21px; height: 21px; border-radius: 5px; background: rgba(148, 163, 184, 0.1); font-size: 8px; font-weight: 950; }
.digest-queue-item strong { overflow: hidden; font-family: "SFMono-Regular", Consolas, monospace; font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.digest-queue-item.active { border-color: rgba(96, 165, 250, 0.56); color: #fff; background: rgba(37, 99, 235, 0.16); }
.digest-queue-item.active span { color: #07111f; background: #7dd3fc; box-shadow: 0 0 15px rgba(125, 211, 252, 0.6); }
.digest-queue-item.done { color: #9ff7e8; border-color: rgba(45, 212, 191, 0.3); }
.digest-queue-item.done span { color: #07111f; background: #2dd4bf; }

.digest-core-panel { display: grid; grid-template-columns: 86px minmax(0, 1fr); align-items: center; gap: 10px; min-width: 0; border-inline: 1px solid rgba(148, 163, 184, 0.15); padding-inline: 14px; }
.digest-core { position: relative; display: grid; place-items: center; width: 78px; height: 78px; border-radius: 50%; background: radial-gradient(circle, rgba(45, 212, 191, 0.32), rgba(37, 99, 235, 0.14) 46%, transparent 48%); }
.digest-core strong { position: relative; z-index: 3; color: #d9fffa; font-size: 18px; text-shadow: 0 0 14px #2dd4bf; }
.digest-ring { position: absolute; inset: 7px; border: 1px solid rgba(45, 212, 191, 0.55); border-radius: 43% 57% 56% 44%; }
.ring-two { inset: 17px 3px; border-color: rgba(96, 165, 250, 0.48); border-radius: 62% 38% 46% 54%; }
.digest-scan { position: absolute; z-index: 2; width: 80%; height: 2px; background: linear-gradient(90deg, transparent, #7dd3fc, transparent); box-shadow: 0 0 12px #7dd3fc; }
.digest-chamber.is-working .ring-one { animation: digestSpin 2.2s linear infinite; }
.digest-chamber.is-working .ring-two { animation: digestSpin 1.7s linear infinite reverse; }
.digest-chamber.is-working .digest-scan { animation: digestScan 1.2s ease-in-out infinite; }
.digest-current { min-width: 0; }
.digest-current small { display: block; color: #7dd3fc; font-size: 8px; font-weight: 900; letter-spacing: 0.1em; }
.digest-current strong { display: block; overflow-wrap: anywhere; margin-top: 5px; color: #fff; font-family: "SFMono-Regular", Consolas, monospace; font-size: 13px; line-height: 1.25; }
.digest-current span { display: block; margin-top: 6px; color: #9fb3c8; font-size: 10px; line-height: 1.35; }

.digest-stages { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; align-items: stretch; }
.digest-stages > div { position: relative; display: grid; align-content: center; gap: 6px; min-width: 0; padding: 8px 6px; border: 1px solid rgba(148, 163, 184, 0.18); border-radius: 7px; color: #72859b; text-align: center; background: rgba(255, 255, 255, 0.025); transition: 180ms ease; }
.digest-stages span { font-size: 8px; font-weight: 950; }
.digest-stages strong { font-size: 9px; line-height: 1.2; }
.digest-stages > div.active { color: #fff; border-color: #60a5fa; background: rgba(37, 99, 235, 0.2); box-shadow: inset 0 -3px #60a5fa, 0 0 18px rgba(96, 165, 250, 0.18); transform: translateY(-2px); }
.digest-stages > div.done { color: #9ff7e8; border-color: rgba(45, 212, 191, 0.4); background: rgba(45, 212, 191, 0.08); }

.ingestion-receipts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; margin: 0 0 10px; }
.receipt-title { grid-column: 1 / -1; display: flex; justify-content: space-between; color: #475569; font-size: 9px; letter-spacing: 0.08em; }
.ingestion-receipts article { display: grid; grid-template-columns: 24px minmax(0, 1fr); align-items: center; gap: 7px; min-width: 0; border: 1px solid rgba(45, 212, 191, 0.25); border-radius: 7px; padding: 7px; background: linear-gradient(135deg, rgba(240, 253, 250, 0.9), rgba(239, 246, 255, 0.8)); }
.receipt-check { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 5px; color: #042f2e; background: #5eead4; font-size: 8px; font-weight: 950; }
.ingestion-receipts strong, .ingestion-receipts small { display: block; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ingestion-receipts strong { color: #172033; font-family: "SFMono-Regular", Consolas, monospace; font-size: 10px; }
.ingestion-receipts small { margin-top: 2px; color: #64748b; font-size: 8px; }

@keyframes digestSpin { to { transform: rotate(360deg); } }
@keyframes digestScan { 0%, 100% { transform: translateY(-22px); opacity: 0.35; } 50% { transform: translateY(22px); opacity: 1; } }

.pipeline {
  display: grid;
  gap: 10px;
}

.ingestion-story {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px minmax(0, 1fr) 34px minmax(0, 1fr) 34px minmax(0, 1fr);
  align-items: stretch;
  gap: 0;
  margin: 0 0 16px;
}

.story-stage {
  position: relative;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 11px;
  min-height: 106px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  border-radius: 10px;
  padding: 14px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 9px 26px rgba(15, 23, 42, 0.05);
  transition: border-color 320ms ease, box-shadow 320ms ease, transform 320ms ease, background 320ms ease;
}

.story-stage::after {
  content: "";
  position: absolute;
  right: -42px;
  bottom: -52px;
  width: 110px;
  height: 110px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(37, 99, 235, 0.12), transparent 68%);
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 320ms ease, transform 480ms ease;
}

.story-stage small,
.story-stage strong,
.story-stage p {
  display: block;
}

.story-stage small {
  color: #64748b;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.06em;
}

.story-stage strong {
  margin-top: 4px;
  color: #172033;
  font-size: 17px;
  line-height: 1.15;
}

.story-stage p {
  margin: 5px 0 0;
  color: #667085;
  font-size: 11px;
  line-height: 1.35;
}

.story-icon {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(100, 116, 139, 0.2);
  border-radius: 10px;
  background: #f8fafc;
  color: #475569;
  font-size: 14px;
  font-weight: 950;
  transition: color 280ms ease, background 280ms ease, border-color 280ms ease, box-shadow 280ms ease;
}

.story-connector {
  position: relative;
  align-self: center;
  height: 2px;
  margin: 0 5px;
  overflow: hidden;
  background: rgba(148, 163, 184, 0.28);
}

.story-connector::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, #2dd4bf, #60a5fa, transparent);
  transform: translateX(-100%);
}

.story-stage.active,
.story-stage.done {
  border-color: rgba(45, 212, 191, 0.55);
  background: linear-gradient(145deg, rgba(240, 253, 250, 0.98), rgba(239, 246, 255, 0.96));
  box-shadow: 0 16px 36px rgba(15, 118, 110, 0.11);
  transform: translateY(-2px);
}

.story-stage.active::after,
.story-stage.done::after {
  opacity: 1;
  transform: scale(1);
}

.story-stage.active .story-icon,
.story-stage.done .story-icon {
  border-color: rgba(45, 212, 191, 0.58);
  background: linear-gradient(135deg, #0f766e, #2563eb);
  color: #ffffff;
  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.2);
}

.story-stage.active .story-icon {
  animation: storyIconPulse 1.45s ease-in-out infinite;
}

.story-stage.done + .story-connector::after,
.story-connector.active::after {
  animation: storyFlow 1.25s linear infinite;
}

#ingestion.is-processing .progress-track {
  box-shadow: 0 0 0 3px rgba(45, 212, 191, 0.07), 0 0 26px rgba(37, 99, 235, 0.12);
}

#ingestion.is-complete .artifact-grid {
  animation: artifactReveal 620ms ease both;
}

@keyframes storyFlow {
  to { transform: translateX(100%); }
}

@keyframes storyIconPulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.08); }
}

@keyframes artifactReveal {
  from { opacity: 0.68; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.pipeline-step {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  align-items: center;
  gap: 12px;
  min-height: 56px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  background: rgba(248, 250, 252, 0.82);
}

.step-dot {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba(148, 163, 184, 0.1);
  color: var(--muted);
  font-weight: 900;
}

.pipeline-step.active {
  border-color: rgba(96, 165, 250, 0.52);
  background: rgba(96, 165, 250, 0.1);
}

.pipeline-step.done .step-dot {
  background: var(--green);
  color: var(--ink);
}

.pipeline-step small {
  color: var(--muted);
}

.console-feed {
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: 440px;
  overflow: auto;
  border-radius: 8px;
  padding: 12px;
  background: #080b10;
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  font-size: 12px;
  line-height: 1.45;
}

.console-line {
  display: grid;
  grid-template-columns: 82px 1fr;
  gap: 10px;
  color: #b7c4d4;
}

.console-line span {
  color: var(--teal);
}

.brain-layout {
  grid-template-columns: minmax(0, 1fr) 340px;
}

.brain-stage {
  position: relative;
  min-height: 640px;
  overflow: hidden;
  border: 1px solid rgba(37, 99, 235, 0.2);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(2, 6, 23, 0.78), rgba(8, 20, 39, 0.2), rgba(2, 6, 23, 0.58)),
    radial-gradient(circle at 48% 48%, rgba(45, 212, 191, 0.18), transparent 38%),
    url("assets/dossiermind-digital-brain-graph-bg.png") center / cover no-repeat;
  box-shadow: 0 28px 70px rgba(15, 23, 42, 0.16);
  animation: brainFieldBreath 12s ease-in-out infinite;
}

.brain-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    linear-gradient(rgba(148, 163, 184, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.08) 1px, transparent 1px);
  background-size: 34px 34px;
  opacity: 0.26;
  pointer-events: none;
  animation: brainGridDrift 18s linear infinite;
}

.brain-stage::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  opacity: 0;
  background: linear-gradient(180deg, transparent 0%, rgba(45, 212, 191, 0.04) 44%, rgba(125, 211, 252, 0.62) 50%, rgba(45, 212, 191, 0.04) 56%, transparent 100%);
  transform: translateY(-100%);
}

.brain-stage.is-entering::after {
  opacity: 1;
  animation: brainScan 1.45s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.brain-ambient {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.brain-ambient i {
  position: absolute;
  left: var(--particle-x);
  top: var(--particle-y);
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #7dd3fc;
  box-shadow: 0 0 16px 4px rgba(45, 212, 191, 0.34);
  opacity: 0.28;
  animation: ambientParticle 7s ease-in-out infinite;
  animation-delay: var(--particle-delay);
}

.brain-live-status {
  position: absolute;
  top: 14px;
  left: 14px;
  z-index: 5;
  display: grid;
  gap: 2px;
  border: 1px solid rgba(125, 211, 252, 0.24);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(3, 13, 25, 0.76);
  color: #ffffff;
  box-shadow: 0 12px 28px rgba(2, 6, 23, 0.28);
  backdrop-filter: blur(12px);
}

.brain-live-status span { color: #5eead4; font-size: 9px; font-weight: 950; letter-spacing: 0.1em; }
.brain-live-status span i { display: inline-block; width: 6px; height: 6px; margin-right: 5px; border-radius: 50%; background: #34d399; box-shadow: 0 0 10px rgba(52, 211, 153, 0.9); animation: livePulse 1.6s ease-in-out infinite; }
.brain-live-status strong { font-size: 12px; }
.brain-live-status small { color: rgba(226, 232, 240, 0.68); font-size: 9px; }

.brain-core-orbit {
  position: absolute;
  z-index: 1;
  width: 208px;
  height: 156px;
  border: 1px solid rgba(45, 212, 191, 0.26);
  border-radius: 50%;
  pointer-events: none;
  animation: coreOrbitSpin 13s linear infinite;
  box-shadow: inset 0 0 40px rgba(45, 212, 191, 0.05), 0 0 32px rgba(96, 165, 250, 0.08);
}

.brain-core-orbit::before { content: ""; position: absolute; inset: 20px 28px; border: 1px dashed rgba(125, 211, 252, 0.2); border-radius: 50%; }
.brain-core-orbit i { position: absolute; width: 7px; height: 7px; border-radius: 50%; background: #5eead4; box-shadow: 0 0 15px rgba(45, 212, 191, 0.9); }
.brain-core-orbit i:nth-child(1) { left: 50%; top: -4px; }
.brain-core-orbit i:nth-child(2) { right: 9px; bottom: 22px; background: #7dd3fc; }
.brain-core-orbit i:nth-child(3) { left: 6px; bottom: 30px; background: #fbbf24; }

.brain-edge {
  position: absolute;
  z-index: 1;
  height: 1px;
  transform-origin: left center;
  background: linear-gradient(90deg, rgba(20, 184, 166, 0.16), rgba(125, 211, 252, 0.68), rgba(37, 99, 235, 0.22));
  opacity: 0.26;
  animation: edgeIdle 5.6s ease-in-out infinite;
  transition: opacity 260ms ease;
}

.brain-edge::after {
  content: "";
  position: absolute;
  left: 0;
  top: -2px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #ccfbf1;
  box-shadow: 0 0 10px #2dd4bf;
  opacity: 0;
}

.brain-edge.visible::after {
  opacity: 0.82;
  animation: edgePacket 3.8s linear infinite;
  animation-delay: var(--packet-delay, 0s);
}

.brain-edge.visible {
  opacity: 0.88;
  animation-name: edgeVisibleIdle;
}

.brain-edge.pulse {
  animation: edgePulse 1.7s ease-in-out infinite;
}

.brain-edge.connected {
  z-index: 2;
  height: 2px;
  opacity: 1;
  background: linear-gradient(90deg, rgba(45, 212, 191, 0.35), #5eead4, #7dd3fc, rgba(37, 99, 235, 0.4));
  filter: drop-shadow(0 0 7px rgba(45, 212, 191, 0.66));
}

.brain-edge.entrance {
  animation: edgeReveal 680ms ease both;
  animation-delay: var(--entrance-delay, 0ms);
}

@keyframes edgePulse {
  0%, 100% { opacity: 0.22; filter: none; }
  50% { opacity: 0.95; filter: drop-shadow(0 0 7px rgba(45, 212, 191, 0.56)); }
}

@keyframes edgeIdle {
  0%, 100% { opacity: 0.22; filter: none; }
  50% { opacity: 0.36; filter: drop-shadow(0 0 5px rgba(125, 211, 252, 0.24)); }
}

@keyframes edgeVisibleIdle {
  0%, 100% { opacity: 0.7; filter: none; }
  50% { opacity: 0.92; filter: drop-shadow(0 0 6px rgba(45, 212, 191, 0.34)); }
}

@keyframes brainFieldBreath {
  0%, 100% { filter: saturate(0.96) brightness(1); }
  50% { filter: saturate(1.08) brightness(1.06); }
}

@keyframes brainGridDrift {
  from { background-position: 0 0, 0 0; }
  to { background-position: 34px 34px, 34px 34px; }
}

@keyframes brainScan {
  from { transform: translateY(-105%); }
  to { transform: translateY(105%); }
}

@keyframes edgeReveal {
  from { opacity: 0; width: 0; }
}

.brain-node {
  position: absolute;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 116px;
  min-height: 54px;
  border: 1px solid rgba(125, 211, 252, 0.34);
  border-radius: 8px;
  padding: 8px;
  background: rgba(248, 250, 252, 0.88);
  color: #102033;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
  opacity: 0.62;
  transform: scale(0.96);
  box-shadow: 0 12px 30px rgba(2, 6, 23, 0.2);
  backdrop-filter: blur(8px);
  transition: opacity 220ms ease, transform 220ms ease, border-color 220ms ease, background 220ms ease;
}

.brain-node.visible {
  opacity: 1;
  transform: scale(1);
  animation: nodeAlive 5.4s ease-in-out infinite;
  animation-delay: var(--float-delay, 0s);
}

.brain-node.related {
  border-color: rgba(96, 165, 250, 0.72);
  box-shadow: 0 0 0 1px rgba(96, 165, 250, 0.13), 0 15px 34px rgba(37, 99, 235, 0.18);
}

.brain-node.entrance {
  animation: nodeReveal 620ms cubic-bezier(0.2, 0.85, 0.2, 1) both;
  animation-delay: var(--entrance-delay, 0ms);
}

.brain-node.core.visible {
  animation: coreAlive 3.4s ease-in-out infinite;
}

@keyframes nodeReveal {
  from { opacity: 0; transform: scale(0.7) translateY(12px); filter: blur(4px); }
}

@keyframes ambientParticle {
  0%, 100% { opacity: 0.12; translate: 0 14px; scale: 0.7; }
  45% { opacity: 0.72; translate: 10px -18px; scale: 1.25; }
  70% { opacity: 0.35; translate: -8px -30px; }
}

@keyframes edgePacket {
  0% { left: 0; opacity: 0; }
  12% { opacity: 0.9; }
  88% { opacity: 0.9; }
  100% { left: calc(100% - 5px); opacity: 0; }
}

@keyframes nodeAlive {
  0%, 100% { translate: 0 0; filter: brightness(1); }
  50% { translate: 0 -4px; filter: brightness(1.04); }
}

@keyframes coreAlive {
  0%, 100% { translate: 0 0; box-shadow: 0 12px 30px rgba(2, 6, 23, 0.2), 0 0 0 0 rgba(45, 212, 191, 0.16); }
  50% { translate: 0 -3px; box-shadow: 0 16px 38px rgba(2, 6, 23, 0.24), 0 0 0 13px rgba(45, 212, 191, 0); }
}

@keyframes coreOrbitSpin { to { transform: rotate(360deg); } }

.brain-node:hover,
.brain-node.active {
  border-color: rgba(45, 212, 191, 0.72);
  background: rgba(240, 253, 250, 0.94);
  box-shadow: 0 0 0 1px rgba(45, 212, 191, 0.18), 0 18px 42px rgba(20, 184, 166, 0.18);
}

.brain-node.core {
  width: 146px;
  min-height: 70px;
  border-color: rgba(45, 212, 191, 0.78);
  background: linear-gradient(135deg, rgba(15, 118, 110, 0.95), rgba(37, 99, 235, 0.88));
  color: #ffffff;
  box-shadow: 0 0 0 1px rgba(45, 212, 191, 0.16), 0 22px 54px rgba(20, 184, 166, 0.25);
}

.brain-node.doc {
  border-color: rgba(96, 165, 250, 0.42);
}

.brain-node.entity {
  border-color: rgba(56, 189, 248, 0.34);
}

.brain-node.period {
  border-color: rgba(45, 212, 191, 0.4);
}

.brain-node.alert {
  border-color: rgba(251, 113, 133, 0.46);
  background: rgba(255, 241, 242, 0.9);
}

.brain-detail {
  display: grid;
  align-content: start;
  gap: 12px;
}

.brain-detail h3 {
  margin: 0;
}

.brain-detail .report-section {
  border-color: rgba(20, 184, 166, 0.18);
  background: linear-gradient(135deg, rgba(240, 253, 250, 0.84), rgba(239, 246, 255, 0.84));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

.brain-detail .detail-list {
  color: #334155;
}

.node-kind {
  width: fit-content;
}

.detail-list,
.report-preview ul {
  margin: 0;
  padding-left: 18px;
  color: var(--soft);
