.report-section-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; margin-bottom: 10px; }
.report-section-heading > div > span { display: block; margin-bottom: 3px; color: #0f766e; font-size: 8px; font-weight: 950; letter-spacing: 0.08em; }
.report-section-heading h4 { margin: 0; }
.report-section-heading > small { max-width: 180px; color: #64748b; font-size: 9px; font-weight: 800; line-height: 1.35; text-align: right; }
.readiness-gauge { display: grid; grid-template-columns: auto minmax(130px, 210px); align-items: center; gap: 9px; border: 1px solid rgba(15, 118, 110, 0.2); border-radius: 9px; padding: 8px 10px; background: #ffffff; }
.readiness-gauge strong { color: #0f766e; font-size: 21px; }
.readiness-gauge small { color: #475569; font-size: 9px; font-weight: 750; line-height: 1.35; }
.report-executive-summary p { font-size: 13px; line-height: 1.65; }
.report-executive-summary p + p { margin-top: 8px; }
.decision-banner { display: grid; grid-template-columns: 120px 1fr; gap: 12px; margin-top: 12px; border-left: 4px solid #0f766e; padding: 10px 12px; background: #ffffff; }
.decision-banner span { color: #0f766e; font-size: 9px; font-weight: 950; text-transform: uppercase; }
.decision-banner strong { font-size: 11px; line-height: 1.45; }
.report-action-plan { display: grid; gap: 7px; margin: 0; padding: 0; list-style: none; }
.report-action-plan li { display: grid; grid-template-columns: 48px 1fr; gap: 10px; align-items: start; border-bottom: 1px solid #dbeafe; padding: 8px 0; }
.report-action-plan span { display: grid; place-items: center; min-height: 28px; border-radius: 7px; color: #ffffff; background: #0f766e; font-size: 9px; font-weight: 900; }
