.report-action-plan p small { display: block; margin-top: 3px; color: #64748b; font-size: 9px; }
.question-checklist { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.question-checklist div { display: grid; grid-template-columns: 30px 1fr; gap: 8px; border: 1px solid #e2e8f0; border-radius: 8px; padding: 9px; background: #ffffff; }
.question-checklist span { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; color: #0f766e; background: #ccfbf1; font-size: 9px; font-weight: 950; }
.question-checklist p { font-size: 10.5px; line-height: 1.42; }
.report-chapter-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 7px; }
.report-chapter-grid div { border: 1px solid #e2e8f0; border-radius: 8px; padding: 9px; background: #ffffff; }
.report-chapter-grid span, .report-chapter-grid strong { display: block; }
.report-chapter-grid span { color: #14b8a6; font-size: 9px; font-weight: 950; }
.report-chapter-grid strong { margin-top: 4px; color: #0f172a; font-size: 10.5px; line-height: 1.35; }
.methodology-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.methodology-grid article { border: 1px solid #dbeafe; border-radius: 8px; padding: 10px; background: #ffffff; }
.methodology-grid strong { display: block; margin-bottom: 4px; color: #0f766e; font-size: 10px; }
.methodology-grid p { color: #475569; font-size: 10px; line-height: 1.48; }

.export-list {
  display: grid;
  gap: 10px;
}

.export-item {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: rgba(248, 250, 252, 0.82);
  color: var(--text);
  text-align: left;
}

.export-item:hover,
.export-item.pdf-file {
  border-color: rgba(15, 118, 110, 0.38);
  background: rgba(15, 118, 110, 0.08);
}

.export-item.pdf-file strong::before {
  content: "PDF";
  display: inline-grid;
  place-items: center;
  min-width: 38px;
  height: 22px;
  border-radius: 6px;
  margin-right: 8px;
  background: #dc2626;
  color: #ffffff;
  font-size: 11px;
  font-weight: 900;
}

.export-item strong {
  display: block;
}

.export-item p {
  margin: 5px 0 0;
  line-height: 1.4;
}

.toast {
  position: fixed;
  right: 22px;
  bottom: 92px;
  z-index: 50;
  display: none;
  max-width: 420px;
  border: 1px solid rgba(45, 212, 191, 0.42);
  border-radius: 8px;
  padding: 14px;
  background: rgba(9, 11, 16, 0.94);
  box-shadow: var(--shadow);
}

.experience-moment {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  padding: 24px;
  pointer-events: none;
  visibility: hidden;
}

.experience-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(2, 6, 23, 0.58);
  opacity: 0;
  backdrop-filter: blur(0);
  transition: opacity 260ms ease, backdrop-filter 260ms ease;
}

.experience-card {
  position: relative;
  width: min(620px, calc(100vw - 40px));
  overflow: hidden;
  border: 1px solid rgba(125, 211, 252, 0.4);
  border-radius: 18px;
  padding: 42px 40px 34px;
  background:
    radial-gradient(circle at 85% 15%, rgba(45, 212, 191, 0.18), transparent 32%),
    linear-gradient(145deg, rgba(7, 16, 31, 0.98), rgba(15, 36, 61, 0.98));
  color: #ffffff;
  box-shadow: 0 42px 100px rgba(2, 6, 23, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  opacity: 0;
  transform: translateY(18px) scale(0.96);
  transition: opacity 260ms ease, transform 360ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.experience-card::after {
  content: "";
  position: absolute;
  inset: auto -20% -80% 22%;
  height: 260px;
  background: radial-gradient(ellipse, rgba(37, 99, 235, 0.32), transparent 66%);
  pointer-events: none;
}

.experience-moment.visible {
  visibility: visible;
}

.experience-moment.visible .experience-backdrop {
  opacity: 1;
  backdrop-filter: blur(5px);
}

.experience-moment.visible .experience-card {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.experience-card small {
  color: #5eead4;
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.experience-card h2 {
  position: relative;
  z-index: 1;
  max-width: 500px;
  margin: 9px 0 10px;
  font-size: clamp(29px, 4vw, 43px);
  line-height: 1.04;
  letter-spacing: -0.035em;
}

.experience-card > p {
  position: relative;
  z-index: 1;
  max-width: 520px;
  margin: 0;
  color: #cbd5e1;
  font-size: 15px;
  line-height: 1.55;
}

.experience-orbit {
  position: absolute;
  top: 26px;
  right: 28px;
  width: 88px;
  height: 88px;
  border: 1px solid rgba(94, 234, 212, 0.24);
  border-radius: 50%;
  animation: orbitSpin 7s linear infinite;
}

.experience-orbit::before,
.experience-orbit::after {
  content: "";
  position: absolute;
  border: 1px solid rgba(96, 165, 250, 0.24);
  border-radius: 50%;
}

.experience-orbit::before { inset: 12px; }
.experience-orbit::after { inset: 28px; background: rgba(45, 212, 191, 0.12); }

.experience-orbit span {
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #5eead4;
  box-shadow: 0 0 16px rgba(45, 212, 191, 0.9);
}

.experience-orbit span:nth-child(1) { top: 4px; left: 39px; }
.experience-orbit span:nth-child(2) { right: 5px; bottom: 19px; background: #7dd3fc; }
.experience-orbit span:nth-child(3) { left: 7px; bottom: 16px; background: #fbbf24; }

.moment-steps {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 24px;
}

.moment-step {
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 9px;
  padding: 10px;
  background: rgba(15, 23, 42, 0.48);
  color: #cbd5e1;
  font-size: 11px;
  font-weight: 800;
  opacity: 0.38;
  transform: translateY(5px);
}

.experience-moment.visible .moment-step {
  animation: momentStep 420ms ease both;
  animation-delay: var(--step-delay, 0ms);
}

.experience-moment.tone-report .experience-card {
  background: radial-gradient(circle at 82% 18%, rgba(96, 165, 250, 0.25), transparent 34%), linear-gradient(145deg, #07101f, #102c45);
}

.experience-moment.tone-revoke .experience-card {
  border-color: rgba(251, 113, 133, 0.46);
  background: radial-gradient(circle at 82% 18%, rgba(244, 63, 94, 0.2), transparent 34%), linear-gradient(145deg, #170a15, #271226);
}

.experience-moment.tone-revoke .experience-card small { color: #fda4af; }
.experience-moment.tone-revoke .experience-orbit span { background: #fb7185; box-shadow: 0 0 16px rgba(251, 113, 133, 0.9); }

@keyframes orbitSpin { to { transform: rotate(360deg); } }

@keyframes momentStep {
  to { opacity: 1; transform: translateY(0); border-color: rgba(94, 234, 212, 0.36); }
}

.primary-btn.is-building {
  cursor: progress;
  filter: saturate(0.75);
}

.scenario-dock {
  position: fixed;
  left: 290px;
  bottom: 22px;
  z-index: 60;
  display: none;
}

.scenario-toggle {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 46px;
  border: 1px solid rgba(45, 212, 191, 0.48);
  border-radius: 8px;
  padding: 0 14px;
  color: #ffffff;
  background: linear-gradient(135deg, #0f766e, #1d4ed8);
  box-shadow: var(--shadow);
  font-weight: 900;
}

.scenario-toggle span {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  background: rgba(6, 16, 21, 0.14);
}

.scenario-menu {
  position: absolute;
  left: 0;
  bottom: 58px;
  display: none;
  width: 370px;
  max-height: min(620px, calc(100vh - 110px));
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 14px;
  background: rgba(255, 255, 255, 0.97);
  box-shadow: var(--shadow);
  backdrop-filter: blur(20px);
}

.scenario-dock.open .scenario-menu {
  display: grid;
  gap: 12px;
}

.scenario-list {
  display: grid;
  gap: 10px;
}

.pdf-modal {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: none;
}

.pdf-modal.visible {
  display: block;
}

.pdf-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.48);
  backdrop-filter: blur(8px);
}

.pdf-viewer {
  position: absolute;
  inset: 28px;
  display: grid;
  grid-template-rows: auto 1fr;
  border: 1px solid rgba(25, 41, 57, 0.16);
  border-radius: 8px;
  background: #eef3f8;
  box-shadow: 0 30px 90px rgba(15, 23, 42, 0.28);
  overflow: hidden;
}

.pdf-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  border-bottom: 1px solid rgba(25, 41, 57, 0.12);
  padding: 14px;
  background: #ffffff;
}

.pdf-toolbar span {
  color: var(--teal);
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.pdf-toolbar h3 {
  margin: 2px 0 0;
}

.pdf-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.icon-btn {
  min-width: 40px;
  padding: 0 10px;
  font-size: 22px;
  line-height: 1;
}

.pdf-paper {
  width: min(900px, calc(100% - 36px));
  margin: 18px auto;
  overflow: auto;
  border: 1px solid rgba(25, 41, 57, 0.12);
  border-radius: 8px;
  padding: 34px;
  background: #ffffff;
  color: var(--text);
  box-shadow: 0 18px 46px rgba(15, 23, 42, 0.13);
}

.pdf-paper .report-section {
  background: #ffffff;
}

.toast.visible {
  display: block;
  animation: toastIn 180ms ease-out;
}

.toast strong {
  display: block;
  margin-bottom: 4px;
}

.toast p {
  margin: 0;
  color: var(--muted);
  line-height: 1.42;
}

@keyframes toastIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.identity-strip {
  display: grid;
  grid-template-columns: 0.92fr 1.1fr 1.45fr 1fr;
  gap: 1px;
  margin: -4px 0 18px;
  overflow: hidden;
  border: 1px solid rgba(15, 118, 110, 0.22);
  border-radius: 10px;
  background: rgba(15, 118, 110, 0.18);
  box-shadow: 0 14px 36px rgba(15, 23, 42, 0.06);
}

.identity-strip > div {
  min-width: 0;
  padding: 12px 14px;
  background: rgba(255, 255, 255, 0.96);
}

.identity-strip span,
.studio-workbench > div > span {
  display: block;
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.identity-strip strong {
  display: block;
  overflow: hidden;
  color: var(--text);
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.identity-strip .identity-trust {
  background: linear-gradient(135deg, rgba(15, 118, 110, 0.96), rgba(29, 78, 216, 0.94));
}

.identity-strip .identity-trust span,
.identity-strip .identity-trust strong { color: #ffffff; }

.studio-workbench {
  display: grid;
  grid-template-columns: minmax(260px, 0.78fr) minmax(0, 1.22fr);
  gap: 20px;
  margin-top: 18px;
  border: 1px solid rgba(15, 118, 110, 0.24);
  border-radius: 12px;
  padding: 20px;
  background: radial-gradient(circle at 8% 20%, rgba(45, 212, 191, 0.18), transparent 34%), linear-gradient(135deg, #071b2f 0%, #0c2941 60%, #123c52 100%);
  color: #ffffff;
  box-shadow: 0 24px 52px rgba(7, 27, 47, 0.18);
}

.studio-workbench h3 { margin: 0 0 8px; font-size: 22px; line-height: 1.18; }
.studio-workbench p { margin: 0; color: rgba(226, 232, 240, 0.82); line-height: 1.5; }

.workbench-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.workbench-card {
  min-height: 84px;
  border: 1px solid rgba(125, 211, 252, 0.22);
  border-radius: 10px;
  padding: 13px;
  background: rgba(255, 255, 255, 0.07);
  color: #ffffff;
  text-align: left;
  backdrop-filter: blur(10px);
}

.workbench-card:hover { border-color: rgba(45, 212, 191, 0.7); background: rgba(45, 212, 191, 0.13); transform: translateY(-1px); }
.workbench-card strong, .workbench-card span { display: block; }
.workbench-card span { margin-top: 6px; color: rgba(226, 232, 240, 0.72); font-size: 12px; }
.workbench-card:disabled { border-color: rgba(148, 163, 184, 0.13); background: rgba(148, 163, 184, 0.08); color: rgba(226, 232, 240, 0.4); cursor: not-allowed; transform: none; }
.workbench-card:disabled span { color: rgba(226, 232, 240, 0.32); }
.studio-workbench.is-locked { border-color: rgba(248, 113, 113, 0.22); }

.nav-item.access-locked { opacity: 0.36; cursor: not-allowed; filter: grayscale(0.7); }
.nav-item.access-locked:hover { border-color: transparent; background: transparent; transform: none; }
.primary-btn.access-locked { border-color: rgba(148, 163, 184, 0.28); background: #cbd5e1; color: #475569; box-shadow: none; cursor: not-allowed; filter: grayscale(0.7); }

.shared-access-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 0 0 12px;
  border: 1px solid rgba(37, 99, 235, 0.22);
  border-radius: 10px;
  padding: 13px 16px;
  background: linear-gradient(90deg, rgba(239, 246, 255, 0.96), rgba(240, 253, 250, 0.94));
  color: #334155;
}

.shared-access-banner strong { color: var(--text); }
.shared-access-banner span { color: var(--muted); font-size: 12px; font-weight: 800; }

.brain-detail-actions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.brain-source-hint { display: block; margin-top: 8px; color: var(--muted); font-size: 10px; line-height: 1.35; }
.report-actions { display: flex; align-items: center; gap: 8px; }
.report-actions select { min-height: 42px; border: 1px solid var(--line); border-radius: 8px; padding: 0 34px 0 12px; background: #ffffff; color: var(--text); font-weight: 800; }

.report-provenance { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin-bottom: 14px; }
.report-provenance div { border: 1px solid rgba(15, 118, 110, 0.18); border-radius: 8px; padding: 10px; background: rgba(240, 253, 250, 0.72); }
.report-provenance span, .report-provenance strong { display: block; }
.report-provenance span { color: var(--muted); font-size: 10px; font-weight: 900; text-transform: uppercase; }
.report-provenance strong { margin-top: 4px; font-size: 12px; }

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
    height: auto;
  }

  .nav-list {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .local-card {
    margin-top: 0;
  }

  .scenario-dock {
    left: 14px;
  }

  .digest-chamber {
    grid-template-columns: minmax(200px, 0.8fr) minmax(250px, 1fr);
  }

  .digest-stages {
    grid-column: 1 / -1;
    min-height: 66px;
  }

  .digest-core-panel { border-right: 0; }

  .crosslink-chamber {
    grid-template-columns: minmax(0, 1fr) 150px;
  }

  .crosslink-stats {
    grid-column: 1 / -1;
  }

  .hero-lab,
  .archive-layout,
  .ingestion-layout,
  .brain-layout,
  .advisor-layout,
  .report-layout,
  .governance-layout,
  .client-grid,
  .artifact-grid {
    grid-template-columns: 1fr;
  }

  .hero-lab,
  .signal-board,
  .hero-copy,
  .archive-panel,
  .pipeline-panel,
  .console-panel,
  .brain-detail,
  .question-bank,
  .chat-panel,
  .export-panel,
  .report-preview {
    min-width: 0;
  }

  .studio-summary {
    grid-template-columns: 1fr;
  }

  .identity-strip,
  .studio-workbench,
  .report-provenance { grid-template-columns: 1fr 1fr; }

  .studio-workbench > div:first-child { grid-column: 1 / -1; }
  .studio-workbench .workbench-actions { grid-column: 1 / -1; }

  .ai-capability-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }

  .ingestion-story {
    grid-template-columns: 1fr 24px 1fr;
    row-gap: 10px;
  }

  .ingestion-story [data-story-stage="documents"] { grid-column: 1; grid-row: 1; }
  .ingestion-story .story-connector:nth-of-type(1) { grid-column: 2; grid-row: 1; }
  .ingestion-story [data-story-stage="markdown"] { grid-column: 3; grid-row: 1; }
  .ingestion-story .story-connector:nth-of-type(2) { display: none; }
  .ingestion-story [data-story-stage="graph"] { grid-column: 1; grid-row: 2; }
  .ingestion-story .story-connector:nth-of-type(3) { display: block; grid-column: 2; grid-row: 2; }
  .ingestion-story [data-story-stage="outputs"] { grid-column: 3; grid-row: 2; }
}

@media (max-width: 780px) {
  .main-content {
    padding: 18px;
    overflow-x: hidden;
  }

