/* Accesso iniziale: la dashboard non è visibile come workspace attivo prima della scelta del ruolo. */
.access-locked { overflow: hidden; }
.access-locked .app-shell { filter: blur(7px); transform: scale(.992); transition: filter .55s ease, transform .55s ease; }

.access-gate {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  overflow: auto;
  padding: 28px;
  color: #e8f1f7;
  background: #07111d;
  transition: opacity .48s ease, transform .48s ease, visibility .48s ease;
}

.access-gate.is-exiting { opacity: 0; transform: scale(1.018); pointer-events: auto; }
.access-gate.is-dismissed { opacity: 0; visibility: hidden; pointer-events: none; }

.access-gate-backdrop {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 18% 12%, rgba(45, 212, 191, .18), transparent 29%),
    radial-gradient(circle at 82% 8%, rgba(96, 165, 250, .17), transparent 31%),
    radial-gradient(circle at 52% 100%, rgba(124, 58, 237, .15), transparent 38%),
    linear-gradient(135deg, #091522, #06101b 58%, #0a1725);
}

.access-gate-backdrop::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: .28;
  background-image: linear-gradient(rgba(148, 163, 184, .06) 1px, transparent 1px), linear-gradient(90deg, rgba(148, 163, 184, .06) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, #000, transparent 88%);
}

.access-gate-shell {
  position: relative;
  width: min(1080px, 100%);
  border: 1px solid rgba(148, 163, 184, .24);
  border-radius: 24px;
  padding: 28px 34px 24px;
  background: linear-gradient(145deg, rgba(15, 29, 44, .88), rgba(8, 19, 31, .9));
  box-shadow: 0 34px 110px rgba(0, 0, 0, .42), inset 0 1px 0 rgba(255, 255, 255, .07);
  backdrop-filter: blur(24px);
  animation: accessGateRise .7s cubic-bezier(.2, .85, .25, 1) both;
}

.access-gate-header,
.access-gate-intro,
.access-gate-footer { display: flex; align-items: center; justify-content: space-between; gap: 18px; }
.access-gate-header { padding-bottom: 22px; border-bottom: 1px solid rgba(148, 163, 184, .16); }
.access-brand { display: flex; align-items: center; gap: 12px; }
.access-brand-mark { position: relative; display: grid; place-items: center; width: 42px; height: 42px; border: 1px solid rgba(45, 212, 191, .52); border-radius: 13px; background: linear-gradient(145deg, rgba(45, 212, 191, .27), rgba(96, 165, 250, .2)); box-shadow: 0 0 28px rgba(45, 212, 191, .15); overflow: hidden; }
.access-brand-mark::before { content: ""; width: 22px; height: 22px; border: 1px solid rgba(226, 232, 240, .75); border-radius: 50%; }
.access-brand-mark::after { content: ""; position: absolute; width: 7px; height: 7px; border-radius: 50%; background: #2dd4bf; box-shadow: 0 0 18px #2dd4bf; }
.access-brand-mark span { position: absolute; width: 31px; height: 1px; background: rgba(96, 165, 250, .64); transform: rotate(-34deg); }
.access-brand-mark i { position: absolute; width: 5px; height: 5px; border-radius: 50%; top: 10px; right: 8px; background: #60a5fa; box-shadow: 0 0 12px #60a5fa; }
.access-brand strong { display: block; font-size: 16px; letter-spacing: .01em; }
.access-brand span { display: block; margin-top: 2px; color: #9fb0c0; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; }
.access-secure-pill { display: inline-flex; align-items: center; gap: 8px; border: 1px solid rgba(45, 212, 191, .24); border-radius: 999px; padding: 8px 11px; color: #b9f3e8; background: rgba(45, 212, 191, .08); font-size: 10px; font-weight: 850; letter-spacing: .07em; text-transform: uppercase; }
.secure-dot { width: 7px; height: 7px; border-radius: 50%; background: #2dd4bf; box-shadow: 0 0 13px rgba(45, 212, 191, .95); animation: accessPulse 1.8s ease-in-out infinite; }

.access-gate-intro { align-items: flex-end; padding: 30px 0 22px; }
.access-gate-intro > div:first-child { max-width: 650px; }
.access-kicker { display: block; margin-bottom: 8px; color: #5eead4; font-size: 10px; font-weight: 900; letter-spacing: .16em; }
.access-gate-intro h1 { margin: 0; color: #f7fbff; font-size: clamp(30px, 4vw, 49px); line-height: 1.04; letter-spacing: -.035em; }
.access-gate-intro p { max-width: 670px; margin: 13px 0 0; color: #aec0cf; font-size: 15px; line-height: 1.55; }
.access-live-status { display: grid; grid-template-columns: auto 1fr; gap: 3px 8px; min-width: 230px; border-left: 1px solid rgba(45, 212, 191, .34); padding: 8px 0 8px 14px; color: #8fa5b7; font-size: 11px; }
.access-live-status .live-dot { grid-row: span 2; margin-top: 3px; }
.access-live-status strong { color: #d8e9f1; font-size: 12px; }

.access-network { display: grid; grid-template-columns: 1fr 54px 1fr 54px auto 54px 1fr; align-items: center; gap: 8px; margin: 4px 0 24px; }
.access-node { justify-self: center; border: 1px solid rgba(148, 163, 184, .25); border-radius: 999px; padding: 7px 10px; color: #bdcad6; background: rgba(148, 163, 184, .08); font-size: 9px; font-weight: 900; letter-spacing: .13em; }
.access-line { position: relative; height: 1px; background: linear-gradient(90deg, rgba(45, 212, 191, .12), rgba(96, 165, 250, .72), rgba(45, 212, 191, .12)); overflow: visible; }
.access-line::after { content: ""; position: absolute; top: -2px; left: 0; width: 5px; height: 5px; border-radius: 50%; background: #5eead4; box-shadow: 0 0 14px #5eead4; animation: accessFlow 2.8s linear infinite; }
.line-b::after { animation-delay: .9s; }
.line-c::after { animation-delay: 1.8s; }
.access-core { position: relative; display: grid; place-items: center; width: 82px; height: 82px; border: 1px solid rgba(45, 212, 191, .55); border-radius: 50%; background: radial-gradient(circle, rgba(45, 212, 191, .23), rgba(37, 99, 235, .08) 56%, transparent 57%); box-shadow: 0 0 36px rgba(45, 212, 191, .19), inset 0 0 22px rgba(96, 165, 250, .16); animation: accessCoreFloat 4.4s ease-in-out infinite; }
.access-core::before, .access-core::after { content: ""; position: absolute; inset: 8px; border: 1px solid rgba(96, 165, 250, .24); border-radius: 50%; animation: accessSpin 8s linear infinite; }
.access-core::after { inset: 17px; border-color: rgba(45, 212, 191, .34); animation-direction: reverse; animation-duration: 5s; }
.access-core i { position: absolute; width: 7px; height: 7px; border-radius: 50%; background: #fbbf24; box-shadow: 0 0 15px #fbbf24; }
.access-core strong { position: relative; z-index: 1; margin-top: 1px; color: #dffdfa; font-size: 9px; letter-spacing: .08em; }
.access-core small { position: absolute; bottom: 18px; color: #89b9c1; font-size: 7px; letter-spacing: .1em; text-transform: uppercase; }

.access-choice-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.access-choice { position: relative; display: grid; gap: 9px; min-height: 236px; border: 1px solid rgba(148, 163, 184, .22); border-radius: 17px; padding: 21px 22px 18px; color: #e8f1f7; background: rgba(255, 255, 255, .035); text-align: left; cursor: pointer; overflow: hidden; transition: transform .25s ease, border-color .25s ease, box-shadow .25s ease, background .25s ease; }
.access-choice::before { content: ""; position: absolute; inset: 0; opacity: 0; background: radial-gradient(circle at 90% 8%, rgba(45, 212, 191, .2), transparent 42%); transition: opacity .25s ease; }
.access-choice:hover, .access-choice:focus-visible { border-color: rgba(94, 234, 212, .72); background: rgba(45, 212, 191, .075); box-shadow: 0 18px 50px rgba(0, 0, 0, .24), 0 0 0 1px rgba(45, 212, 191, .09); transform: translateY(-4px); }
.access-choice:hover::before, .access-choice:focus-visible::before { opacity: 1; }
.access-choice-studio:hover, .access-choice-studio:focus-visible { border-color: rgba(147, 197, 253, .72); background: rgba(96, 165, 250, .075); }
.access-choice > * { position: relative; z-index: 1; }
.access-choice-top { display: flex; align-items: center; justify-content: space-between; }
.access-choice-icon { display: grid; place-items: center; width: 34px; height: 34px; border: 1px solid rgba(45, 212, 191, .38); border-radius: 10px; color: #5eead4; background: rgba(45, 212, 191, .1); font-size: 18px; font-weight: 900; }
.access-choice-studio .access-choice-icon { border-color: rgba(147, 197, 253, .42); color: #bfdbfe; background: rgba(96, 165, 250, .11); }
.access-choice-tag { color: #80ded0; font-size: 9px; font-weight: 900; letter-spacing: .13em; }
.access-choice-studio .access-choice-tag { color: #a9c9fb; }
.access-choice-title { margin-top: 3px; color: #f8fbff; font-size: 23px; font-weight: 850; letter-spacing: -.025em; }
.access-choice-subtitle { color: #c6d6e0; font-size: 13px; font-weight: 700; }
.access-choice-description { max-width: 470px; min-height: 40px; color: #91a7b6; font-size: 12px; line-height: 1.45; }
.access-choice-footer { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; margin-top: auto; padding-top: 12px; border-top: 1px solid rgba(148, 163, 184, .14); }
.access-choice-footer b { display: block; margin-bottom: 3px; color: #7c93a3; font-size: 9px; letter-spacing: .11em; text-transform: uppercase; }
.access-choice-footer strong { display: block; color: #dceaf2; font-size: 12px; }
.access-enter-arrow { color: #5eead4; font-size: 28px; line-height: .7; transition: transform .25s ease; }
.access-choice:hover .access-enter-arrow { transform: translateX(5px); }
.access-choice-studio .access-enter-arrow { color: #93c5fd; }

.access-gate-footer { justify-content: flex-start; flex-wrap: wrap; gap: 18px 28px; padding-top: 20px; color: #8298a8; font-size: 10px; }
.footer-check { display: inline-grid; place-items: center; width: 16px; height: 16px; margin-right: 5px; border: 1px solid rgba(45, 212, 191, .45); border-radius: 50%; color: #5eead4; font-style: normal; font-weight: 900; }
.access-legal-notice { margin: 15px 0 0; border-top: 1px solid rgba(148, 163, 184, .12); padding-top: 12px; color: #6f8596; font-size: 9px; line-height: 1.45; letter-spacing: .015em; }

@keyframes accessGateRise { from { opacity: 0; transform: translateY(16px) scale(.985); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes accessPulse { 50% { opacity: .42; transform: scale(.72); } }
@keyframes accessFlow { from { transform: translateX(0); opacity: 0; } 12% { opacity: 1; } 88% { opacity: 1; } to { transform: translateX(54px); opacity: 0; } }
@keyframes accessCoreFloat { 50% { transform: translateY(-4px); box-shadow: 0 0 48px rgba(45, 212, 191, .27), inset 0 0 26px rgba(96, 165, 250, .2); } }
@keyframes accessSpin { to { transform: rotate(360deg); } }

@media (max-width: 780px) {
  .access-gate { align-items: start; padding: 14px; }
  .access-gate-shell { padding: 20px 17px 18px; border-radius: 18px; }
  .access-gate-header, .access-gate-intro { align-items: flex-start; flex-direction: column; }
  .access-gate-header { gap: 13px; }
  .access-secure-pill { align-self: flex-start; }
  .access-gate-intro { padding: 23px 0 15px; }
  .access-gate-intro h1 { font-size: 34px; }
  .access-gate-intro p { font-size: 13px; }
  .access-live-status { width: 100%; }
  .access-network { grid-template-columns: 1fr 28px auto 28px 1fr; margin-bottom: 18px; }
  .access-network .node-b, .access-network .line-b { display: none; }
  .access-network .line-c { grid-column: 4; }
  .access-network .node-c { grid-column: 5; }
  .access-core { width: 70px; height: 70px; }
  .access-choice-grid { grid-template-columns: 1fr; }
  .access-choice { min-height: 210px; }
  .access-gate-footer { display: grid; gap: 9px; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

