#archiveSearch{width:100%;padding:12px;margin-bottom:12px;border:1px solid #c4d1df;border-radius:9px;font:inherit;color:#173347;background:#fff}

.bank-mapping-grid,.bank-result-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.bank-mapping-grid label{display:grid;gap:8px}.note-editor select{padding:10px;border:1px solid #c4d1df;border-radius:9px;font:inherit;background:#fff;color:#173347;max-width:100%}.bank-result-grid strong{font-size:21px;color:#173347}.bank-result-grid .source-note-card{margin:4px 0}@media(max-width:650px){.bank-mapping-grid,.bank-result-grid{grid-template-columns:1fr}}

.bank-calculation-area{padding:24px;border:1px solid #dce4ed;border-radius:16px;background:#fff}.bank-calculation-area .bank-mapping-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.bank-calculation-area .bank-result-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.note-editor input[type=checkbox]{width:auto;margin:3px 0}.bank-confirmation{display:flex;align-items:flex-start;gap:10px}.bank-result-grid .source-note-card{background:#f4f8fa}@media(max-width:850px){.bank-calculation-area .bank-mapping-grid,.bank-calculation-area .bank-result-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){.bank-calculation-area .bank-mapping-grid,.bank-calculation-area .bank-result-grid{grid-template-columns:1fr}}

.checklist-entry{display:grid;gap:10px;margin:12px 0;padding:16px;border:1px solid #dce4ed;border-radius:12px;background:#f6f9fb;overflow-wrap:anywhere}.checklist-entry .source-card-status{justify-self:start}.note-editor fieldset{display:grid;gap:12px;padding:16px;border:1px solid #c4d1df;border-radius:12px;min-width:0}.note-editor legend{padding:0 8px;color:#173347;font-weight:600}.note-editor select{min-width:0;width:100%}
.assertion-preview{white-space:pre-wrap;overflow-wrap:anywhere;max-height:220px;overflow:auto;padding:14px;background:#f4f8fa;border-radius:10px;line-height:1.6}.assertion-preview:empty{display:none}.assertion-card .ghost-btn{max-width:100%;white-space:normal;overflow-wrap:anywhere;margin:6px 6px 0 0}.note-editor .bank-confirmation[hidden]{display:none}
.report-period-controls{min-width:0;margin:16px 0 24px;padding:20px;border:1px solid #dce4ed;border-radius:14px;background:#f6f9fb}.report-period-controls[hidden]{display:none}.report-period-controls>div{max-height:280px;overflow:auto;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.report-period-controls .bank-confirmation{font-size:13px;line-height:1.6;overflow-wrap:anywhere}.report-period-controls input[type=checkbox]{flex-shrink:0;accent-color:#168a8c}.report-period-controls input[type=date]{max-width:240px}@media(max-width:650px){.report-period-controls>div{grid-template-columns:1fr}}
.report-period-controls>div[hidden]{display:none}

.advisor-context-controls { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin-top:18px; padding:18px; border:1px solid var(--line, #dbe5e7); border-radius:14px; background:#f5f9f9; }
.advisor-context-controls label {display:flex; flex-direction:column; gap:7px; font-size:13px; font-weight:600;}
.advisor-context-controls .advisor-context-label,.advisor-context-controls p {grid-column:1 / -1;}
.advisor-context-controls textarea,.advisor-context-controls input,.advisor-context-controls select {width:100%; box-sizing:border-box; padding:11px; border:1px solid #d4dfe1; border-radius:9px; background:white; color:#263b42; font:inherit;}
.advisor-context-controls textarea {min-height:86px; resize:vertical;}
.advisor-context-controls button {grid-column:1 / -1; justify-self:start;}
#advisorHistory {margin-top:24px;}
#advisorHistory article {padding:16px; border:1px solid #dbe5e7; border-radius:12px; margin:12px 0; background:#fff;}
@media(max-width:640px){.advisor-context-controls{grid-template-columns:1fr;}}

.memory-workbench > select,.memory-workbench > input {font:inherit; padding:10px; border:1px solid #d4dfe1; border-radius:9px; background:white; margin:4px 8px 10px 0; max-width:100%;}
.memory-workbench > input{width:70px;}
.memory-workbench > button{margin:4px 8px 12px 0;}
.memory-workbench .source-note-card{font-weight:400;}
.memory-page-preview{margin:16px 0; border:1px solid #dbe5e7; border-radius:10px; overflow:hidden; background:white;}
.memory-page-preview img{display:block; width:100%; height:auto;}
.memory-workbench textarea{display:block; width:100%; box-sizing:border-box; min-height:80px; padding:10px; font:inherit; border:1px solid #d4dfe1; border-radius:9px; margin:10px 0;}

#advisorHistory form textarea,#advisorHistory form select{display:block;width:100%;box-sizing:border-box;padding:10px;font:inherit;border:1px solid #d4dfe1;border-radius:9px;margin:10px 0;}
#advisorHistory form textarea{min-height:90px;}
#reportAdvisor{max-width:400px;padding:10px;font:inherit;border:1px solid #d4dfe1;border-radius:9px;}

.runtime-connections{margin:18px 0;display:grid;gap:12px;}
.runtime-connection-card{padding:16px;background:#fff;border:1px solid #dbe5e7;border-left:4px solid #0c8c8c;border-radius:12px;overflow-wrap:anywhere;}
.runtime-connection-card h4{margin:8px 0;font-size:1rem;color:#173a4b;}
.runtime-connection-card small{color:#526d78;}
.runtime-connection-card blockquote{margin:12px 0;padding:12px;border-left:3px solid #cadfe2;background:#f6fafb;white-space:pre-wrap;font-size:.9rem;}
.runtime-citation{margin:12px 0}.runtime-citation>p{white-space:pre-wrap;overflow-wrap:anywhere}.runtime-citation>small{color:#526278}.runtime-citation blockquote{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace;margin:12px 0}

/* Quick links reveal existing authorized views; hidden until signed in. */
.scenario-dock:not([hidden]) { display: block; }
.scenario-dock[hidden] { display: none; }

/* Live graph: actual tenant nodes and provenance, original brain backdrop. */
.live-brain-map{margin:20px 0 28px;border:1px solid #d4e1e7;border-radius:20px;overflow:hidden;background:#f5f9fc}.live-brain-map>h3{padding:22px 22px 0;margin:0;color:#19384c}.live-brain-map>.runtime-note{margin:0}.live-map-toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:10px 20px 20px}.live-map-toolbar select,.live-map-toolbar input{padding:10px;border:1px solid #cbdde7;border-radius:9px;background:white;min-width:0;max-width:100%}.live-map-toolbar span{font-size:12px;color:#40586a}.live-map-viewport{height:610px;overflow:auto;position:relative;background:#071a2c url('assets/dossiermind-digital-brain-graph-bg.png') center/cover no-repeat;overscroll-behavior:contain}.live-map-space{position:relative;margin:auto}.live-map-scene{position:absolute;top:0;left:0;transform-origin:top left}.live-map-edges{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.live-map-edges line{stroke:#6dc5ce;stroke-width:1.5;opacity:.32}.live-map-edges line.proposed{stroke:#f9cc78;stroke-dasharray:6 5}.live-map-edges line.selected{opacity:1;stroke-width:3}.live-map-node{position:absolute;transform:translate(-50%,-50%);width:142px;min-height:62px;border:1px solid #487b99;border-radius:14px;color:#f1f8ff;background:rgba(12,37,57,.96);padding:10px;text-align:center;box-shadow:0 6px 20px #0004;cursor:pointer}.live-map-node small{display:block;color:#99c3d9;font-size:10px;margin-bottom:4px}.live-map-node strong{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:12px;line-height:1.35}.live-map-node[data-kind='tenant']{width:175px;min-height:80px;border:2px solid #5eead4;background:#123d49;box-shadow:0 0 35px #2dd4bf40}.live-map-node[data-kind='wiki_proposal'],.live-map-node[data-kind='entity_proposal']{border-color:#c7a567}.live-map-node[data-kind='human_note'],.live-map-node[data-kind='human_assertion']{border-color:#af9ee9}.live-map-node:hover,.live-map-node.active{border-color:#5eead4;box-shadow:0 0 0 3px #5eead440}.live-map-node.related{background:#20455e}.live-map-node:focus-visible{outline:3px solid white;outline-offset:4px}.live-map-detail{padding:22px;background:white;border-top:1px solid #d4e1e7;color:#19384c}.live-map-detail h4{font-size:20px;margin:6px 0 16px;overflow-wrap:anywhere}.live-map-detail p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.55}.live-map-detail button{margin:5px 8px 5px 0;max-width:100%;white-space:normal;text-align:left}.live-map-related{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:20px;padding-top:15px;border-top:1px solid #dbe5ed}.live-map-related strong{width:100%}.live-map-node[hidden]{display:none}@media(max-width:650px){.live-map-viewport{height:480px}.live-map-toolbar input{width:100%}.live-map-detail{padding:16px}}

/* Original pre-event brain illustration, embedded to avoid new asset routes. */
.live-map-viewport{background-image:linear-gradient(#071a2c33,#071a2c55),url("data:image/png;base64,");}
